left = {1: 2, 2: 4, 3: 6}    # left child of each node
right = {1: 3, 2: 5, 3: 7}   # right child of each node
root = 1

def in_order(node):
    if node is None: return []
    return in_order(left.get(node)) + [node] + in_order(right.get(node))

def pre_order(node):
    if node is None: return []
    return [node] + pre_order(left.get(node)) + pre_order(right.get(node))

def post_order(node):
    if node is None: return []
    return post_order(left.get(node)) + post_order(right.get(node)) + [node]

print("In-order:  ", in_order(root))
print("Pre-order: ", pre_order(root))
print("Post-order:", post_order(root))
